package cn.mop.api;
import cn.mop.domain.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class ExplicitOperationalMetricsControllerTest {
    static final String ACTOR="65000000-0000-4000-8000-000000000001",TENANT="65000000-0000-4000-8000-000000000002";
    PlatformRepository platform;ExplicitOperationalMetricsController controller;ObjectMapper mapper=new ObjectMapper();
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);controller=new ExplicitOperationalMetricsController(platform);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",1,true)));}
    MockHttpServletRequest request(String body){var r=new MockHttpServletRequest("POST","/api/v1/operations/explicit-comparisons");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setContent(body.getBytes(StandardCharsets.UTF_8));r.setContentType("application/json");return r;}
    String input(){return "{\"elapsed_millis\":[\"9\",\"2\",\"1\",\"3\"],\"staffing\":{\"active_tenants\":\"30\",\"on_call_fte\":\"1.5\",\"second_line_fte\":\"1\"}}";}
    Map<?,?> data(String input){return (Map<?,?>)((Map<?,?>)controller.compare(request(input))).get("data");}
    Map<?,?> part(Map<?,?> value,String key){return (Map<?,?>)value.get(key);}
    @Test void exactStringsAndExplicitOnlyGates(){var d=data(input());assertEquals(TENANT,d.get("tenant_id"));assertEquals("2.5",part(d,"sample_median").get("median_millis"));assertEquals("2.5",part(d,"staffing").get("explicit_total_fte"));assertEquals("12",part(d,"staffing").get("tenants_per_fte"));assertEquals(false,d.get("business_data_queried"));assertEquals(false,d.get("formal_metrics_available"));assertEquals(false,d.get("comparison_saved"));assertNull(part(d,"staffing").get("target_met"));assertNull(part(d,"sample_median").get("effective_processing_duration"));verify(platform).membership(ACTOR,TENANT);verifyNoMoreInteractions(platform);}
    @Test void nullEmptyUnknownAndZeroNotConflated(){var d=data("{\"elapsed_millis\":null,\"staffing\":null}");assertEquals("INPUT_UNAVAILABLE",part(d,"sample_median").get("reason"));assertNull(part(d,"sample_median").get("sample_count"));d=data("{\"elapsed_millis\":[],\"staffing\":null}");assertEquals("EMPTY_SAMPLE",part(d,"sample_median").get("reason"));assertNull(part(d,"sample_median").get("median_millis"));d=data("{\"elapsed_millis\":[null,\"0\"],\"staffing\":null}");assertEquals(1,part(d,"sample_median").get("unknown_count"));assertEquals("UNKNOWN_SAMPLE",part(d,"sample_median").get("reason"));d=data(input().replace("[\"9\",\"2\",\"1\",\"3\"]","[\"0\"]"));assertEquals("0",part(d,"sample_median").get("median_millis"));}
    @Test void missingFteAndZeroDenominatorStayUnresolvedOrUndefined(){var d=data(input().replace("\"1.5\"","null"));assertNull(part(d,"staffing").get("tenants_per_fte"));assertEquals(List.of("on_call_fte"),part(d,"staffing").get("missing_inputs"));d=data(input().replace("\"on_call_fte\":\"1.5\"","\"on_call_fte\":\"0\"").replace("\"second_line_fte\":\"1\"","\"second_line_fte\":\"0\""));assertEquals("ZERO_FTE",part(d,"staffing").get("reason"));assertNull(part(d,"staffing").get("tenants_per_fte"));}
    @Test void unsafeJavascriptIntegerStaysExactAndRepeatingRatioIsString(){var d=data(input().replace("\"30\"","\"9007199254740993\"").replace("\"1.5\"","\"0\""));assertEquals("9007199254740993",part(d,"staffing").get("tenants_per_fte"));d=data(input().replace("\"30\"","\"1\"").replace("\"1.5\"","\"2\""));assertEquals("0.3333333333333333333333333333333333",part(d,"staffing").get("tenants_per_fte"));}
    @Test void rejectUnknownMissingAndForgedFields()throws Exception{for(String body:List.of("{}","null","[]","{\"elapsed_millis\":null}",input().replace("\"staffing\":", "\"tenant_id\":null,\"staffing\":"),input().replace("\"active_tenants\"", "\"approved_tenants\"")))assertEquals(400,assertThrows(DomainException.class,()->data(body)).status);}
    @Test void requireCanonicalBoundedDecimalStrings()throws Exception{for(JsonNode value:List.of(mapper.readTree("1"),mapper.readTree("true"),new TextNode("01"),new TextNode("-1"),new TextNode("1e2"),new TextNode(" 1"),new TextNode("1."),new TextNode("1".repeat(41)),new TextNode("0."+"1".repeat(41)))){var body=(ObjectNode)mapper.readTree(input());((ObjectNode)body.get("staffing")).set("on_call_fte",value);assertEquals(400,assertThrows(DomainException.class,()->data(body.toString())).status);}}
    @Test void durationMustBeIntegerStringOrNull()throws Exception{for(JsonNode value:List.of(mapper.readTree("1"),new TextNode("1.5"),new TextNode("-1"),mapper.createObjectNode())){var body=(ObjectNode)mapper.readTree(input());body.putArray("elapsed_millis").add(value);assertThrows(DomainException.class,()->data(body.toString()));}}
    @Test void maximumSampleCountAndBodyBoundary(){String base="{\"elapsed_millis\":[%s],\"staffing\":null}";assertEquals(10000,part(data(base.formatted(String.join(",",Collections.nCopies(10000,"\""+"9".repeat(40)+"\"")))),"sample_median").get("sample_count"));assertThrows(DomainException.class,()->data(base.formatted(String.join(",",Collections.nCopies(10001,"\"1\"")))));assertThrows(DomainException.class,()->data(" ".repeat(ExplicitOperationalMetricsController.MAX_BODY_BYTES+1)));}
    @Test void rejectDuplicateKeysTrailingAndDeepJson(){for(String body:List.of("{\"elapsed_millis\":null,\"elapsed_millis\":null,\"staffing\":null}",input()+" {}","[[[[0]]]]",input().replace("\"on_call_fte\":\"1.5\"","\"on_call_fte\":null,\"on_call_fte\":\"1.5\"")))assertThrows(DomainException.class,()->data(body));}
    @Test void authorizationBeforeParsingAndEveryCallRechecksMembership(){for(String role:List.of("viewer","tadmin","msp","unexpected")){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,1,true)));assertEquals(403,assertThrows(DomainException.class,()->data("not json")).status);}when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",1,false)));assertEquals(401,assertThrows(DomainException.class,()->data(input())).status);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.empty());assertEquals(401,assertThrows(DomainException.class,()->data(input())).status);}
    @Test void missingOrMalformedSessionAndQueriesRejected(){var r=request(input());r.setUserPrincipal(null);assertEquals(401,assertThrows(DomainException.class,()->controller.compare(r)).status);var malformed=request(input());malformed.getSession().setAttribute("mop.tenant_id",42);assertEquals(401,assertThrows(DomainException.class,()->controller.compare(malformed)).status);var q=request(input());q.addParameter("tenant_id",TENANT);assertEquals(400,assertThrows(DomainException.class,()->controller.compare(q)).status);}
}
